-- Add the new BESS-only document variant; retain every historical archive and existing v4 renderer.
INSERT INTO document_format_archives(version,fingerprint,payload) VALUES(3,'3a12fc6226bebe725fd0b42922d3e75444d2cba9cfb11cc9662b8a37717249d6',$ubl_bess_format${"label":"UBL BESS installation IPO/PT addition; existing v4 renderers unchanged","documentLayoutVersion":4,"bessPolicy":"ubl-bess-approved-proportional-v1","historicalArchiveVersion":2,"files":{"server/orders/report-v4.ts":"import { displayUnit } from \"../boq/unit.js\";\nimport { appendPeachtreePage } from \"./peachtree-report-v4.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport { ipoPresentation } from \"./presentation.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nconst clean = (s: unknown) =>\n  String(s ?? \"\")\n    .replaceAll(\"\u00d7\", \"x\")\n    .replace(/[\u2013\u2014]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nexport function buildIpoPdf(s: any, number?: string, division = s.peachtree, options:{includePt?:boolean}={}) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: number ?? \"Draft IPO\",\n    author: \"Power Zone Engineering & Services\",\n  });\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\n    number ? \"INTERNAL PURCHASE ORDER\" : \"DRAFT INTERNAL PURCHASE ORDER\",\n    14,\n    37,\n  );\n  pdf.setFontSize(8);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 42);\n  const i = s.input;\n  const view = ipoPresentation({\n    ...s,\n    quotationType: division ?? s.quotationType,\n  });\n  const taxDeal=s.quotationType?.saleType !== \"Cash Deal\";\n  const entries = [\n    [\"IPO / Job reference\",number ?? \"DRAFT\",\"Quotation reference\",s.quotationNumber || \"Not available\"],\n    [\"Company to invoice\",i.invoiceCompany,\"Tax deal\",taxDeal?\"Yes\":\"No\"],\n    [\"Prepared by\",\"Atif\",\"Checked by\",\"Atif\"],\n    [\"Customer\",s.customer.name,\"Site / branch\",`${s.siteName ?? \"Not entered\"} / ${s.siteCode ?? \"Not entered\"}`],\n    [\"Customer PO / approval\",i.poNumber || i.evidenceNotes || \"Not entered\",\"PO / approval date\",i.orderDate],\n    ...(taxDeal?[[\"Customer NTN\",i.customerNtn || \"Not entered\",\"Customer STRN\",i.customerStrn || \"Not entered\"]]:[]),\n    [\"Billing address\",i.billingAddress || \"Not entered\",\"Customer contact\",`${i.contactPerson || s.customer.contactPerson || \"Not entered\"} / ${i.phone || s.customer.phone || \"Not entered\"}`],\n  ];\n  autoTable(pdf, {\n    startY: 46,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.4 },\n    columnStyles: {\n      0: { cellWidth: 27 },\n      1: { cellWidth: 64 },\n      2: { cellWidth: 27 },\n      3: { cellWidth: 64 },\n    },\n    body: [\n      ...entries,\n      [\"Quotation type\", quotationTypeLabel(division ?? s), \"\", \"\"],\n    ].map((row) => row.map(clean)),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 4,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.3 },\n    headStyles: { fillColor: [61, 63, 146], fontSize: 7 },\n    head: [[\"Description\", \"Qty\", \"Unit\", view.included ? \"Rate\" : \"Rate excl. GST\", view.included ? \"Amount\" : \"Amount excl. GST\"]],\n    columnStyles: {0:{cellWidth:100},1:{halign:\"center\",cellWidth:10},2:{halign:\"center\",cellWidth:12},3:{halign:\"right\"},4:{halign:\"right\"}},\n    body:view.rows.map(l=>[clean(l.description)+(/solar|panel/i.test(l.description)?' - Revise at IRR stage.':''),l.qty,displayUnit(l.unit,l.qty),money(l.rate),money(l.amount)]),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 3,\n    theme: \"plain\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 8, cellPadding: 1.2 },\n    body: [\n      ...(!view.included\n        ? [\n            [\"Grand total before tax\", {content:money(view.amount),styles:{halign:\"right\" as const}}],\n            ...view.taxSummary.filter(tax=>s.allocation.policy!==\"fixed-bank-ups\"||Number(tax.amount)!==0).map((tax)=>[tax.label,{content:money(tax.amount),styles:{halign:\"right\" as const}}]),\n          ]\n        : []),\n      [\"GRAND TOTAL (PKR)\", {content:money(s.allocation.total),styles:{halign:\"right\",fontStyle:\"bold\"}}],\n      ...(i.paymentMode ? [[\"Payment mode\", clean(i.paymentMode)]] : []),\n      ...(i.salesSource ? [[\"Sales source\", clean(i.salesSource)]] : []),\n      ...(i.remarks ? [[\"Remarks\", clean(i.remarks)]] : []),\n      ...(view.rows.some(r=>/solar|panel/i.test(r.description)) ? [[\"Panel wattage\", \"To be confirmed from IRR.\"]] : []),\n    ],\n  });\n  if (division && options.includePt!==false) appendPeachtreePage(pdf, s, division, number ?? \"DRAFT IPO\");\n  drawReportFooter(\n    pdf,\n    number\n      ? `${number} / IPO & Peachtree Division`\n      : \"DRAFT IPO & Peachtree Division\",\n  );\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/orders/peachtree-report-v4.ts":"import {CASH_PROFIT_NOTE, retainedGst} from \"../commercial/deal.js\";\nimport {Decimal} from \"decimal.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport { drawReportLogo, drawReportFooter, reportBottomMargin } from \"../reports/branding.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport type { peachtreeDivision } from \"./peachtree.js\";\nimport {ptDisplayRows} from './pt-detail.js';\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nconst text = (v: unknown) =>\n  String(v ?? \"\")\n    .replace(/[\u2013\u2014]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nexport function appendPeachtreePage(\n  pdf: jsPDF,\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  pdf.addPage();\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\"PEACHTREE DIVISION\", 14, 38);\n  pdf.setFontSize(9);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 44);\n  autoTable(pdf, {\n    startY: 50,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    body: [\n      [\"IPO\", number],\n      [\"Quotation\", text(s.quotationNumber)],\n      [\"BOQ\", text(s.boqNumber)],\n      [\"Customer\", text(s.customer.name)],\n      [\"Entry basis\", d.basis],\n      [\"Quotation type\", text(quotationTypeLabel(d))],\n    ],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 7,\n    theme: \"grid\",\n    headStyles: { fillColor: [61, 63, 146] },\n    footStyles: { fillColor: [61, 63, 146] },\n    margin:{left:14,right:14,bottom:reportBottomMargin},\n    styles: { fontSize: 8, cellPadding: 2.3 },\n    columnStyles: {0:{cellWidth:26},1:{cellWidth:37},2:{cellWidth:81},3:{halign:\"right\",cellWidth:38}},\n    head: [[\"PT phase\", \"Item ID\", \"Description / quantity\", d.saleType === \"Cash Deal\" ? \"Selling value (PKR)\" : \"Selling excl. GST (PKR)\"]],\n    body: ptDisplayRows(d).map((p:any)=>[p.name,text(p.itemId||'Not allocated'),text(p.description || \"Description not recorded\"),money(p.amount)]),\n    foot: [[\"PHASE TOTAL\",\"\",\"\", {content:money(d.phaseTotal),styles:{halign:\"right\"}}]],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 6,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    columnStyles: { 1: { halign: \"right\" } },\n    body:\n      d.version >= 2 && d.taxMode === \"Tax Included\"\n        ? [[\"IPO payable\", money(d.ipoPayable)]]\n        : [\n            [\"IPO total before tax\", money(d.ipoBeforeTax)],\n            [\"IPO tax (separate reconciliation)\", money(d.ipoTax)],\n            [\"IPO payable\", money(d.ipoPayable)],\n          ],\n  });\n  const policy = d.policy === \"fixed-bank-ups-proportional-cost\" ? \"Approved UPS selling value excluding GST is allocated proportionally to the frozen component and installation costs. Accepted payable and GST remain unchanged.\" : \"EPC excludes the separately shown Earthing, Electrical Labour and Deliveries. Allocation uses saved BOQ category costs; accepted totals and GST remain unchanged.\";\n  pdf.setFontSize(8);\n  pdf.setFont('helvetica','normal');\n  pdf.text(\n    pdf.splitTextToSize(\n      text(\n        `${policy} ${retainedGst(d)?CASH_PROFIT_NOTE:\"GST is excluded from profit.\"}`,\n      ),\n      180,\n    ),\n    14,\n    (pdf as any).lastAutoTable.finalY + 5,\n  );\n}\nexport function buildPeachtreePdf(\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: `${number} - Peachtree Division`,\n    author: \"Power Zone Engineering & Services\",\n  });\n  appendPeachtreePage(pdf, s, d, number);\n  pdf.deletePage(1);\n  drawReportFooter(pdf, `${number} / Peachtree Division`);\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/orders/document-renderers.ts":"import { buildIpoPdf as bessIpo } from \"./report-ubl-bess.js\";\nimport { buildPeachtreePdf as bessPt } from \"./peachtree-report-ubl-bess.js\";\nimport { buildIpoPdf as originalIpo } from \"./report.js\";\nimport { buildPeachtreePdf as originalPt } from \"./peachtree-report.js\";\nimport { buildIpoPdf as currentIpo } from \"./report-v4.js\";\nimport { buildPeachtreePdf as currentPt } from \"./peachtree-report-v4.js\";\n// Historical snapshots retain their original archived renderer.\nexport const buildIpoPdf = (\n  s: any,\n  number?: string,\n  division = s.peachtree,\n  options: { includePt?: boolean } = {},\n) =>\n  s.allocation?.policy === \"ubl-bess-approved-proportional-v1\"\n    ? bessIpo(s, number, division, options)\n    : s.documentLayoutVersion >= 4\n      ? currentIpo(s, number, division, options)\n      : originalIpo(s, number, division);\nexport const buildPeachtreePdf = (s: any, d: any, number: string) =>\n  s.allocation?.policy === \"ubl-bess-approved-proportional-v1\"\n    ? bessPt(s, d, number)\n    : s.documentLayoutVersion >= 4\n      ? currentPt(s, d, number)\n      : originalPt(s, d, number);\n","server/orders/report-ubl-bess.ts":"import { displayUnit } from \"../boq/unit.js\";\nimport { appendPeachtreePage } from \"./peachtree-report-ubl-bess.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport { ipoPresentation } from \"./presentation.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nconst clean = (s: unknown) =>\n  String(s ?? \"\")\n    .replaceAll(\"\u00d7\", \"x\")\n    .replace(/[\u2013\u2014]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nexport function buildIpoPdf(\n  s: any,\n  number?: string,\n  division = s.peachtree,\n  options: { includePt?: boolean } = {},\n) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: number ?? \"Draft IPO\",\n    author: \"Power Zone Engineering & Services\",\n  });\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\n    number ? \"INTERNAL PURCHASE ORDER\" : \"DRAFT INTERNAL PURCHASE ORDER\",\n    14,\n    37,\n  );\n  pdf.setFontSize(8);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 42);\n  const i = s.input;\n  const view = ipoPresentation({\n    ...s,\n    quotationType: division ?? s.quotationType,\n  });\n  const taxDeal = s.quotationType?.saleType !== \"Cash Deal\";\n  const entries = [\n    [\n      \"IPO / Job reference\",\n      number ?? \"DRAFT\",\n      \"Quotation reference\",\n      s.quotationNumber || \"Not available\",\n    ],\n    [\n      \"Company to invoice\",\n      i.invoiceCompany,\n      \"Tax deal\",\n      taxDeal ? \"Yes\" : \"No\",\n    ],\n    [\"Prepared by\", \"Atif\", \"Checked by\", \"Atif\"],\n    [\n      \"Customer\",\n      s.customer.name,\n      \"Site / branch\",\n      `${s.siteName ?? \"Not entered\"} / ${s.siteCode ?? \"Not entered\"}`,\n    ],\n    [\n      \"Customer PO / approval\",\n      i.poNumber || i.evidenceNotes || \"Not entered\",\n      \"PO / approval date\",\n      i.orderDate,\n    ],\n    ...(taxDeal\n      ? [\n          [\n            \"Customer NTN\",\n            i.customerNtn || \"Not entered\",\n            \"Customer STRN\",\n            i.customerStrn || \"Not entered\",\n          ],\n        ]\n      : []),\n    [\n      \"Billing address\",\n      i.billingAddress || \"Not entered\",\n      \"Customer contact\",\n      `${i.contactPerson || s.customer.contactPerson || \"Not entered\"} / ${i.phone || s.customer.phone || \"Not entered\"}`,\n    ],\n  ];\n  autoTable(pdf, {\n    startY: 46,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.4 },\n    columnStyles: {\n      0: { cellWidth: 27 },\n      1: { cellWidth: 64 },\n      2: { cellWidth: 27 },\n      3: { cellWidth: 64 },\n    },\n    body: [\n      ...entries,\n      [\"Quotation type\", quotationTypeLabel(division ?? s), \"\", \"\"],\n    ].map((row) => row.map(clean)),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 4,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.3 },\n    headStyles: { fillColor: [61, 63, 146], fontSize: 7 },\n    head: [\n      [\n        \"SR#\",\n        \"Description\",\n        \"Qty\",\n        \"Unit\",\n        view.included ? \"Rate\" : \"Rate excl. GST\",\n        view.included ? \"Amount\" : \"Amount excl. GST\",\n      ],\n    ],\n    columnStyles: {\n      0: { cellWidth: 8 },\n      1: { cellWidth: 92 },\n      2: { halign: \"center\", cellWidth: 10 },\n      3: { halign: \"center\", cellWidth: 12 },\n      4: { halign: \"right\" },\n      5: { halign: \"right\" },\n    },\n    body: view.rows.map((l, index) => [\n      String(index + 1),\n      clean(l.description),\n      l.qty,\n      displayUnit(l.unit, l.qty),\n      money(l.rate),\n      money(l.amount),\n    ]),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 3,\n    theme: \"plain\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 8, cellPadding: 1.2 },\n    body: [\n      ...(!view.included\n        ? [\n            [\n              \"Grand total before tax\",\n              {\n                content: money(view.amount),\n                styles: { halign: \"right\" as const },\n              },\n            ],\n            ...view.taxSummary\n              .filter((tax) => Number(tax.amount) !== 0)\n              .map((tax) => [\n                tax.label,\n                {\n                  content: money(tax.amount),\n                  styles: { halign: \"right\" as const },\n                },\n              ]),\n          ]\n        : []),\n      [\n        \"GRAND TOTAL (PKR)\",\n        {\n          content: money(s.allocation.total),\n          styles: { halign: \"right\", fontStyle: \"bold\" },\n        },\n      ],\n      ...(i.paymentMode ? [[\"Payment mode\", clean(i.paymentMode)]] : []),\n      ...(i.salesSource ? [[\"Sales source\", clean(i.salesSource)]] : []),\n      ...(i.remarks ? [[\"Remarks\", clean(i.remarks)]] : []),\n    ],\n  });\n  if (division && options.includePt !== false)\n    appendPeachtreePage(pdf, s, division, number ?? \"DRAFT IPO\");\n  drawReportFooter(\n    pdf,\n    number\n      ? `${number} / IPO & Peachtree Division`\n      : \"DRAFT IPO & Peachtree Division\",\n  );\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/orders/peachtree-report-ubl-bess.ts":"import { CASH_PROFIT_NOTE, retainedGst } from \"../commercial/deal.js\";\nimport { Decimal } from \"decimal.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport type { peachtreeDivision } from \"./peachtree.js\";\nimport { ptDisplayRows } from \"./pt-detail.js\";\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nconst text = (v: unknown) =>\n  String(v ?? \"\")\n    .replace(/[\u2013\u2014]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nexport function appendPeachtreePage(\n  pdf: jsPDF,\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  pdf.addPage();\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\"PEACHTREE DIVISION\", 14, 38);\n  pdf.setFontSize(9);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 44);\n  autoTable(pdf, {\n    startY: 50,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    body: [\n      [\"IPO\", number],\n      [\"Quotation\", text(s.quotationNumber)],\n      [\"BOQ\", text(s.boqNumber)],\n      [\"Customer\", text(s.customer.name)],\n      [\"Site / branch\", text(`${s.siteName} / ${s.siteCode}`)],\n      [\"Entry basis\", d.basis],\n      [\"Quotation type\", text(quotationTypeLabel(d))],\n    ],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 7,\n    theme: \"grid\",\n    headStyles: { fillColor: [61, 63, 146] },\n    footStyles: { fillColor: [61, 63, 146] },\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 8, cellPadding: 2.3 },\n    columnStyles: {\n      0: { cellWidth: 10 },\n      1: { cellWidth: 25 },\n      2: { cellWidth: 35 },\n      3: { cellWidth: 74 },\n      4: { halign: \"right\", cellWidth: 38 },\n    },\n    head: [\n      [\n        \"SR#\",\n        \"PT phase\",\n        \"Item ID\",\n        \"Description / quantity\",\n        d.saleType === \"Cash Deal\"\n          ? \"Selling value (PKR)\"\n          : \"Selling excl. GST (PKR)\",\n      ],\n    ],\n    body: ptDisplayRows(d).flatMap((p: any, index: number) => [\n      [\n        String(index + 1),\n        p.name,\n        text(p.itemId || \"Not allocated\"),\n        text(p.description || \"Description not recorded\"),\n        money(p.amount),\n      ],\n      ...(p.name === \"BMS\"\n        ? [\n            [\n              \"\",\n              \"BESS Total\",\n              \"\",\n              \"Subtotal\",\n              money(\n                d.phases\n                  .filter((p) =>\n                    [\"Inverter\", \"Batteries\", \"BMS\"].includes(p.name),\n                  )\n                  .reduce(\n                    (n: Decimal, p: any) => n.add(p.amount),\n                    new Decimal(0),\n                  )\n                  .toFixed(2),\n              ),\n            ],\n          ]\n        : []),\n    ]),\n    foot: [\n      [\n        { content: \"PHASE TOTAL\", colSpan: 4 },\n        { content: money(d.phaseTotal), styles: { halign: \"right\" } },\n      ],\n    ],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 6,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    columnStyles: { 1: { halign: \"right\" } },\n    body:\n      d.version >= 2 && d.taxMode === \"Tax Included\"\n        ? [[\"IPO payable\", money(d.ipoPayable)]]\n        : [\n            [\"IPO total before tax\", money(d.ipoBeforeTax)],\n            [\"IPO tax (separate reconciliation)\", money(d.ipoTax)],\n            [\"IPO payable\", money(d.ipoPayable)],\n          ],\n  });\n  const policy =\n    d.policy === \"ubl-bess-approved-proportional-v1\"\n      ? \"Approved UBL BESS agreement: negotiated discount allocated proportionally across every PT entry. GST and payable reconcile to the accepted fixed price. Cable adjustment is reserved for later actual-usage invoicing; no initial deduction.\"\n      : d.policy === \"fixed-bank-ups-proportional-cost\"\n        ? \"Approved UPS selling value excluding GST is allocated proportionally to the frozen component and installation costs. Accepted payable and GST remain unchanged.\"\n        : \"EPC excludes the separately shown Earthing, Electrical Labour and Deliveries. Allocation uses saved BOQ category costs; accepted totals and GST remain unchanged.\";\n  pdf.setFontSize(8);\n  pdf.setFont(\"helvetica\", \"normal\");\n  pdf.text(\n    pdf.splitTextToSize(\n      text(\n        `${policy} ${retainedGst(d) ? CASH_PROFIT_NOTE : \"GST is excluded from profit.\"}`,\n      ),\n      180,\n    ),\n    14,\n    (pdf as any).lastAutoTable.finalY + 5,\n  );\n}\nexport function buildPeachtreePdf(\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: `${number} - Peachtree Division`,\n    author: \"Power Zone Engineering & Services\",\n  });\n  appendPeachtreePage(pdf, s, d, number);\n  pdf.deletePage(1);\n  drawReportFooter(pdf, `${number} / Peachtree Division`);\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n"}}$ubl_bess_format$::jsonb);
